//! IEEE OUI/MA-L/MA-M/MA-S vendor lookup.
//!
//! Two data sources are supported:
//!
//! * An **embedded** table generated by `tools/gen-oui.py` from the public IEEE
//!   registry. It is stored as a newline-delimited `<HEX>\t<vendor-index>` file
//!   plus a vendor dictionary, so the ~40k prefixes cost well under a megabyte.
//! * A **runtime** IEEE registry CSV (`--oui-file`), which the operator can
//!   refresh without rebuilding.
//!
//! Lookup is longest-prefix-first: MA-S (36 bit) beats MA-M (28 bit) beats MA-L
//! (24 bit), mirroring how the registry delegates address space.

use std::borrow::Cow;
use std::collections::HashMap;
use std::path::Path;
use std::sync::OnceLock;

use crate::engine::error::{Error, Result};
use crate::engine::model::MacAddr;

const EMBEDDED_PREFIXES: &str = include_str!("../../data/oui_prefixes.tsv");
const EMBEDDED_VENDORS: &str = include_str!("../../data/oui_vendors.txt");

/// Prefix lengths recognised by the IEEE registry, longest first.
const PREFIX_LENGTHS: [usize; 3] = [9, 7, 6];

/// A parsed vendor database.
///
/// The prefix table is kept as one flat string and binary-searched through an
/// offset index, which avoids materialising 40k individual `String`s.
///
/// `Clone` is cheap: the embedded table is `Cow::Borrowed`, so cloning only
/// copies the offset index and the vendor vector.
#[derive(Clone)]
pub struct OuiDb {
    prefixes: Cow<'static, str>,
    /// Byte offset of the start of each line in `prefixes`.
    offsets: Vec<u32>,
    vendors: Vec<Cow<'static, str>>,
}

impl std::fmt::Debug for OuiDb {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("OuiDb")
            .field("prefixes", &self.offsets.len())
            .field("vendors", &self.vendors.len())
            .finish()
    }
}

impl OuiDb {
    /// The table compiled into the binary.
    pub fn embedded() -> &'static OuiDb {
        static DB: OnceLock<OuiDb> = OnceLock::new();
        DB.get_or_init(|| {
            OuiDb::from_parts(
                Cow::Borrowed(EMBEDDED_PREFIXES),
                EMBEDDED_VENDORS.lines().map(Cow::Borrowed).collect(),
            )
            .expect("embedded OUI tables are generated by tools/gen-oui.py and must be valid")
        })
    }

    /// Empty database, useful for tests.
    pub fn empty() -> OuiDb {
        OuiDb {
            prefixes: Cow::Borrowed(""),
            offsets: Vec::new(),
            vendors: Vec::new(),
        }
    }

    fn from_parts(prefixes: Cow<'static, str>, vendors: Vec<Cow<'static, str>>) -> Result<OuiDb> {
        let mut offsets = Vec::new();
        let mut position = 0usize;
        for line in prefixes.split_inclusive('\n') {
            let trimmed = line.trim_end_matches(['\n', '\r']);
            if !trimmed.is_empty() {
                offsets.push(position as u32);
            }
            position += line.len();
        }

        let db = OuiDb {
            prefixes,
            offsets,
            vendors,
        };

        // Guard against a corrupt or hand-edited table: every line must be
        // `<HEX>\t<index>` with the index in range.
        for i in 0..db.offsets.len() {
            let (prefix, index) = db
                .line_parts(i)
                .ok_or_else(|| Error::parse("OUI table", format!("malformed line {i}")))?;
            if prefix.is_empty() || index >= db.vendors.len() {
                return Err(Error::parse(
                    "OUI table",
                    format!(
                        "line {i} references vendor {index} out of {} entries",
                        db.vendors.len()
                    ),
                ));
            }
        }

        Ok(db)
    }

    /// Number of registered prefixes.
    pub fn len(&self) -> usize {
        self.offsets.len()
    }

    pub fn is_empty(&self) -> bool {
        self.offsets.is_empty()
    }

    fn line_str(&self, i: usize) -> &str {
        let start = self.offsets[i] as usize;
        let rest = &self.prefixes[start..];
        match rest.find('\n') {
            Some(end) => &rest[..end],
            None => rest,
        }
    }

    fn line_parts(&self, i: usize) -> Option<(&str, usize)> {
        let line = self.line_str(i).trim_end_matches('\r');
        let (prefix, index) = line.split_once('\t')?;
        Some((prefix, index.trim().parse().ok()?))
    }

    fn prefix_at(&self, i: usize) -> &str {
        let line = self.line_str(i);
        match line.find('\t') {
            Some(tab) => &line[..tab],
            None => line,
        }
    }

    fn vendor_at(&self, i: usize) -> Option<&str> {
        let (_, index) = self.line_parts(i)?;
        self.vendors.get(index).map(|v| v.as_ref())
    }

    /// Find the vendor owning an uppercase hex prefix of exactly `key.len()`.
    fn search(&self, key: &str) -> Option<&str> {
        if key.is_empty() || self.offsets.is_empty() {
            return None;
        }
        // Prefix table is sorted, so a standard binary search applies.
        let idx = self.offsets.partition_point(|&offset| {
            let line = {
                let rest = &self.prefixes[offset as usize..];
                match rest.find('\n') {
                    Some(end) => &rest[..end],
                    None => rest,
                }
            };
            let prefix = match line.find('\t') {
                Some(tab) => &line[..tab],
                None => line,
            };
            prefix < key
        });

        if idx < self.offsets.len() && self.prefix_at(idx) == key {
            self.vendor_at(idx)
        } else {
            None
        }
    }

    /// Resolve a MAC to its registered organization, or `None` when the address
    /// is locally administered / unregistered.
    pub fn lookup(&self, mac: &MacAddr) -> Option<&str> {
        // A randomised address (iOS, Android, Windows and macOS all shuffle the
        // locally administered bit) has no registry entry: whatever prefix it
        // happens to hit would be a coincidence, and a wrong vendor is worse
        // than none.
        if mac.is_locally_administered() {
            return None;
        }
        let hex = mac.to_hex();
        for len in PREFIX_LENGTHS {
            if hex.len() < len {
                continue;
            }
            if let Some(vendor) = self.search(&hex[..len]) {
                return Some(vendor);
            }
        }
        None
    }

    /// Human-readable attribution that also explains the common "no vendor"
    /// cases instead of leaving a blank cell.
    pub fn describe(&self, mac: &MacAddr) -> String {
        if mac.is_multicast() {
            return "multicast/broadcast".to_string();
        }
        if let Some(vendor) = self.lookup(mac) {
            return vendor.to_string();
        }
        if mac.is_locally_administered() {
            "locally administered (virtual)".to_string()
        } else {
            "unregistered prefix".to_string()
        }
    }

    /// Load an IEEE registry CSV, e.g. `oui.csv` from standards-oui.ieee.org.
    ///
    /// Both the modern 4-column format (`Registry,Assignment,Organization Name,
    /// Organization Address`) and a bare `Assignment,Name` layout are accepted.
    pub fn from_ieee_csv(path: impl AsRef<Path>) -> Result<OuiDb> {
        let path = path.as_ref();
        let file = std::fs::File::open(path).map_err(|e| Error::io(path, e))?;
        let mut reader = csv::ReaderBuilder::new().flexible(true).from_reader(file);

        let headers = reader
            .headers()
            .map_err(|e| Error::parse("OUI CSV", e.to_string()))?
            .clone();

        let assignment_col = find_column(&headers, &["assignment", "oui", "prefix"])
            .ok_or_else(|| Error::parse("OUI CSV", "no `Assignment` column found"))?;
        let name_col = find_column(
            &headers,
            &["organization name", "organization", "vendor", "name"],
        )
        .ok_or_else(|| Error::parse("OUI CSV", "no `Organization Name` column found"))?;
        let registry_col = find_column(&headers, &["registry"]);

        let mut prefixes: Vec<(String, String)> = Vec::new();
        for record in reader.records() {
            let record = record.map_err(|e| Error::parse("OUI CSV", e.to_string()))?;

            if let Some(col) = registry_col {
                if let Some(registry) = record.get(col) {
                    let registry = registry.trim();
                    if !registry.is_empty() && !matches!(registry, "MA-L" | "MA-M" | "MA-S") {
                        continue;
                    }
                }
            }

            let assignment = record
                .get(assignment_col)
                .unwrap_or("")
                .trim()
                .to_ascii_uppercase();
            let name = record.get(name_col).unwrap_or("").trim();
            if assignment.is_empty()
                || name.is_empty()
                || !assignment.chars().all(|c| c.is_ascii_hexdigit())
            {
                continue;
            }
            prefixes.push((assignment, name.to_string()));
        }

        if prefixes.is_empty() {
            return Err(Error::parse(
                "OUI CSV",
                format!("{} contained no usable assignments", path.display()),
            ));
        }

        Self::from_records(prefixes)
    }

    fn from_records(mut records: Vec<(String, String)>) -> Result<OuiDb> {
        records.sort_by(|a, b| a.0.cmp(&b.0));

        let mut vendors: Vec<Cow<'static, str>> = Vec::new();
        let mut vendor_index: HashMap<String, usize> = HashMap::new();
        let mut prefixes = String::new();

        for (prefix, vendor) in records {
            let index = *vendor_index.entry(vendor.clone()).or_insert_with(|| {
                vendors.push(Cow::Owned(vendor.clone()));
                vendors.len() - 1
            });
            prefixes.push_str(&prefix);
            prefixes.push('\t');
            prefixes.push_str(&index.to_string());
            prefixes.push('\n');
        }

        OuiDb::from_parts(Cow::Owned(prefixes), vendors)
    }
}

fn find_column(headers: &csv::StringRecord, candidates: &[&str]) -> Option<usize> {
    headers.iter().position(|h| {
        let h = h.trim().to_ascii_lowercase();
        candidates.iter().any(|c| h == *c)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn mac(s: &str) -> MacAddr {
        s.parse().unwrap()
    }

    #[test]
    fn embedded_table_loads_and_is_sorted() {
        let db = OuiDb::embedded();
        assert!(
            db.len() > 30_000,
            "expected the full registry, got {}",
            db.len()
        );
        for i in 1..db.len() {
            assert!(
                db.prefix_at(i - 1) <= db.prefix_at(i),
                "table must be sorted for binary search (index {i})"
            );
        }
    }

    #[test]
    fn resolves_known_vendors() {
        let db = OuiDb::embedded();
        assert_eq!(
            db.lookup(&mac("d0:57:7e:35:f5:2f")),
            Some("Intel Corporate")
        );
        assert_eq!(
            db.lookup(&mac("2c:a0:42:30:3c:7e")),
            Some("Huawei Device Co., Ltd.")
        );
        assert_eq!(
            db.lookup(&mac("44:03:2c:af:69:0f")),
            Some("Intel Corporate")
        );
    }

    #[test]
    fn explains_unregistered_and_virtual_addresses() {
        let db = OuiDb::embedded();
        // Locally administered (docker bridge style).
        assert_eq!(db.lookup(&mac("06:fb:4d:6d:5d:81")), None);
        assert!(
            db.describe(&mac("06:fb:4d:6d:5d:81"))
                .contains("locally administered")
        );
        // Multicast.
        assert!(db.describe(&mac("01:00:5e:00:00:01")).contains("multicast"));
    }

    #[test]
    fn lookup_handles_short_prefixes_gracefully() {
        let db = OuiDb::empty();
        assert!(db.is_empty());
        assert_eq!(db.lookup(&mac("aa:bb:cc:dd:ee:ff")), None);
    }

    #[test]
    fn parses_ieee_csv_roundtrip() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("oui.csv");
        std::fs::write(
            &path,
            "Registry,Assignment,Organization Name,Organization Address\n\
             MA-L,286FB9,\"Nokia Shanghai Bell Co., Ltd.\",\"Somewhere\"\n\
             MA-L,D0577E,Intel Corporate,\"Hillsboro\"\n\
             MA-S,1434567,Tiny Corp,\"Nowhere\"\n\
             MA-L,ZZZZZZ,Bad Row,\"Ignored\"\n",
        )
        .unwrap();

        let db = OuiDb::from_ieee_csv(&path).unwrap();
        assert_eq!(db.len(), 3, "the malformed row must be skipped");
        assert_eq!(
            db.lookup(&mac("d0:57:7e:00:11:22")),
            Some("Intel Corporate")
        );
        assert_eq!(
            db.lookup(&mac("28:6f:b9:00:11:22")),
            Some("Nokia Shanghai Bell Co., Ltd.")
        );
        assert_eq!(db.lookup(&mac("14:34:56:70:00:00")), Some("Tiny Corp"));
    }

    #[test]
    fn a_randomised_address_has_no_vendor() {
        // Every modern phone and laptop shuffles bit 1 of the first octet to
        // avoid being tracked. The registry says nothing about such an address,
        // and a coincidental prefix match would be a wrong answer, so the table
        // is not even consulted.
        let db = OuiDb::from_records(vec![
            ("123456".into(), "Coincidence".into()),
            ("103456".into(), "Real Vendor".into()),
        ])
        .unwrap();

        assert_eq!(
            db.lookup(&mac("12:34:56:00:00:01")),
            None,
            "0x12 has the locally administered bit set"
        );
        assert_eq!(
            db.lookup(&mac("10:34:56:00:00:01")),
            Some("Real Vendor"),
            "0x10 is the same shape with the bit clear"
        );
    }

    #[test]
    fn longest_prefix_wins() {
        // A 7-hex MA-M assignment must shadow the 6-hex MA-L underneath it.
        // `a8:aa:ab:...` has hex prefix A8AAAB, so its 28-bit key is A8AAAB0.
        // (The first octet is universally administered: a locally administered
        // address is refused before the table is consulted.)
        let db = OuiDb::from_records(vec![
            ("A8AAAA".into(), "Broad Owner".into()),
            ("A8AAAB0".into(), "Narrow Owner".into()),
        ])
        .unwrap();
        assert_eq!(db.lookup(&mac("a8:aa:aa:00:00:01")), Some("Broad Owner"));
        assert_eq!(db.lookup(&mac("a8:aa:ab:00:00:01")), Some("Narrow Owner"));
    }
}
